        max_sum = float('-inf')
        current_sum = 0

        for num in arr:
            current_sum = max(num, current_sum + num)
            max_sum = max(max_sum, current_sum)

        return max_sum

    n = len(nums)
    total_length = n * k

    # Calculate the maximum subarray sum for the original array
    original_max_sum = max_sub_array_sum(nums)

    # Calculate the maximum subarray sum for the repeated array
    max_sum = 0
    for i in range(n):
        current_sum = 0
        for j in range(i, i + n):
            current_sum += nums[j % n]
        max_sum = max(max_sum, current_sum)

    # Consider the case where the maximum subarray sum spans across the repetitions
    for i in range(n):
        for j in range(i, n):
            current_sum = 0
            for m in range(i, j + 1):
                current_sum += nums[m]
            max_sum = max(max_sum, current_sum)

    # Consider the case where the maximum subarray sum spans across multiple repetitions
    for i in range(n):
        current_sum = 0
        for j in range(i, n * k):
            current_sum += nums[j % n]
        max_sum = max(max_sum, current_sum)

